static std::complex<double> FPMFsc_unsym(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
