  auto zab = [&za, &zb](int j1, int j2, int j3) {
    return za(j1, j2) * zb(j2, j3);
  };

  std::complex<double> FPMFsc_unsym_value =
      -0.5 * za(j1, j3)
        / (za(j1, j2) * za(j2, j3) * zb(j5, j6) * t(j1, j2, j3) * zab2(j1, j2, j3, j4))
